#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct  {
    int id;
    int score;
}
Student;
int compare_students(const void* left, const void* right)  {
    const Student* a = (const Student*)left;
    const Student* b = (const Student*)right;
    if (a->score != b->score)  {
        return a->score > b->score ? -1 : 1;
    }
    return a->id - b->id;
}
int main(void)  {
    int n;
    // 输入位置就是原编号减一，排序时必须保留每位同学身份。
    scanf("%d", &n);
    Student students[2000];
    for (int i = 0; i < n; ++i)  {
        students[i].id = i + 1;
        scanf("%d", &students[i].score);
    }
    // 先按积分降序，再按原编号升序；同分输出顺序不能任意改变。
    qsort(students, n, sizeof(Student), compare_students);
    int rank = 1;
    for (int i = 0; i < n; ++i)  {
        if (i == 0 || students[i].score != students[i - 1].score)  {
            // 新分数组之前全部是更高分者，所以名次是当前位置加一；同分沿用名次。
            rank = i + 1;
        }
        // 输出原编号和并列名次，积分不属于输出字段。
        printf("%d %d\n", students[i].id, rank);
    }
    return 0;
}

