import java.io.*;
import java.util.*;
public class Main  {
    static final class FastScanner  {
        private final InputStream input = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int position = 0;
        private int length = 0;
        private int read() throws IOException  {
            if (position == length)  {
                length = input.read(buffer);
                position = 0;
                if (length < 0)  {
                    return -1;
                }
            }
            return buffer[position++];
        }
        String next() throws IOException  {
            int value;
            do  {
                value = read();
            }
            while (value <= 32 && value != -1);
            StringBuilder token = new StringBuilder();
            while (value > 32 && value != -1)  {
                token.append((char) value);
                value = read();
            }
            return token.toString();
        }
        int nextInt() throws IOException  {
            return Integer.parseInt(next());
        }
        long nextLong() throws IOException  {
            return Long.parseLong(next());
        }
    }
    public static void main(String[] args) throws Exception  {
        FastScanner scanner = new FastScanner();
        // 输入位置就是原编号减一，排序时必须保留每位同学身份。
        int n = scanner.nextInt();
        int[] scores = new int[n];
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++)  {
            scores[i] = scanner.nextInt();
            order[i] = i;
        }
        // 先按积分降序，再按原编号升序；同分输出顺序不能任意改变。
        Arrays.sort(order, (a, b) ->  {
            if (scores[a] != scores[b])  {
                return Integer.compare(scores[b], scores[a]);
            }
            return Integer.compare(a, b);
        }
        );
        StringBuilder answer = new StringBuilder();
        int rank = 1;
        for (int i = 0; i < n; i++)  {
            if (i == 0 || scores[order[i]] != scores[order[i - 1]])  {
                // 新分数组之前全部是更高分者，所以名次是当前位置加一；同分沿用名次。
                rank = i + 1;
            }
            // 输出原编号和并列名次，积分不属于输出字段。
            answer.append(order[i] + 1).append(' ').append(rank).append('\n');
        }
        System.out.print(answer);
    }
}

