use std::io:: {
    self, Read
}
;
fn main()  {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    // 输入位置就是原编号减一，排序时必须保留每位同学身份。
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let scores: Vec<i64> = tokens.map(|token| token.parse().unwrap()).collect();
    let mut order: Vec<usize> = (0..n).collect();
    // 先按积分降序，再按原编号升序；同分输出顺序不能任意改变。
    order.sort_by(|&a, &b| scores[b].cmp(&scores[a]).then(a.cmp(&b)));
    let mut rank = 1usize;
    let mut answer = String::new();
    for position in 0..n  {
        let index = order[position];
        if position == 0 || scores[index] != scores[order[position - 1]]  {
            // 新分数组之前全部是更高分者，所以名次是当前位置加一；同分沿用名次。
            rank = position + 1;
        }
        // 输出原编号和并列名次，积分不属于输出字段。
        answer.push_str(&format!("{} {}\n", index + 1, rank));
    }
    print!("{}", answer);
}
